{
  "technical_and_design_decisions": [
    "Externalize protoutil, BCCSP, MSP, and discovery client into reusable Go modules or packages with public APIs suitable for Fabric Go SDK consumption.",
    "Preserve externally visible behavior and wire compatibility wherever possible, using compatibility wrappers only when required to avoid unnecessary Fabric application changes.",
    "Refactor statebased so its only Hyperledger Fabric imports are generated protobuf packages; replace direct uses of fabric/comm, fabric/protoutil, pkg/errors, and policy helpers with local or standard-library implementations.",
    "Refactor entities to remove Fabric logging and BCCSP-related dependency chains while retaining its current functional behavior.",
    "Use Go standard-library errors and logging, or narrowly scoped external dependencies, rather than importing Fabric internal implementation packages.",
    "Keep protobuf message types sourced from fabric-protos-go and avoid duplicating generated protobuf definitions.",
    "Validate dependency isolation with go list and module/package dependency checks, in addition to unit and integration tests.",
    "Update the marbles02_private sample instructions to strip newline characters from base64 shell output using tr -d '\\n' where required."
  ],
  "assumptions": [
    "The increment includes implementation and migration work for all user stories U1 through U8, not merely documentation or issue analysis.",
    "Existing Fabric source code, tests, build scripts, and the Fabric Go SDK copies are available and compile in a reproducible Go development environment.",
    "Externalized packages can initially be published under the existing Hyperledger Fabric ecosystem ownership and do not require a new governance process or production release operation.",
    "The existing public behavior and supported cryptographic algorithms of BCCSP, MSP, protoutil, and discovery client must be retained; redesign of their functional APIs is out of scope.",
    "No new consensus, membership protocol, cryptographic algorithm, or discovery protocol is introduced.",
    "Generated protobuf code is consumed from fabric-protos-go; regenerating or redesigning the protobuf schemas is out of scope.",
    "Cross-platform validation is limited to the supported Go environments and shell command documentation; a full Windows shell implementation is not required.",
    "One workday represents one developer day of productive effort and includes coding, local testing, and technical investigation, but excludes elapsed waiting time.",
    "The estimate includes normal code review remediation and CI troubleshooting but not major undocumented defects in the existing Fabric codebase.",
    "The externalized packages require API documentation, licensing/header checks, and basic release-ready packaging, but not long-term maintenance after delivery."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository assessment and dependency baseline",
      "activity_description": "Inspect the existing Fabric implementations, SDK copies, package APIs, tests, module boundaries, and current go list dependency graphs; define extraction boundaries and migration points for all affected packages.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A2",
      "activity_name": "Decouple statebased package",
      "activity_description": "Remove imports and transitive dependency paths through fabric/comm, fabric/protoutil, pkg/errors, cauthdsl, and related Fabric implementation packages; introduce protobuf-only or local equivalents and update unit tests.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A3",
      "activity_name": "Decouple entities package",
      "activity_description": "Remove Fabric logging, BCCSP, and other unwanted transitive dependencies from the entities package; preserve behavior, update package-level code, and add dependency regression checks.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A4",
      "activity_name": "Externalize protoutil",
      "activity_description": "Extract the reusable protoutil implementation from Fabric, define the external package API and module layout, migrate imports and tests, resolve internal-package assumptions, and verify compatibility with SDK use cases.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize BCCSP",
      "activity_description": "Extract BCCSP interfaces, factories, software provider, utilities, idemix-related integration points, and supporting tests from Fabric/SDK copies; remove SDK modifications where feasible and establish reusable package boundaries.",
      "most_likely_effort": 25
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize MSP",
      "activity_description": "Extract MSP interfaces and implementations, migrate dependencies and tests, reconcile differences between Fabric and SDK copies, preserve identity and serialization behavior, and provide an SDK-consumable API.",
      "most_likely_effort": 25
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize discovery client",
      "activity_description": "Extract the discovery client and required supporting types, migrate the SDK away from its copied implementation, preserve request/response behavior, and update associated tests and documentation.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A8",
      "activity_name": "Fabric and SDK integration migration",
      "activity_description": "Update Fabric and Fabric Go SDK imports, module dependencies, build metadata, interfaces, adapters, and compatibility code so consumers use the externalized packages without duplicated implementations.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A9",
      "activity_name": "Testing and dependency-isolation verification",
      "activity_description": "Run and repair unit, package, integration, and compatibility tests; verify statebased and entities dependency graphs; check supported Go versions and detect accidental reintroduction of prohibited Fabric imports.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A10",
      "activity_name": "Marbles private-chaincode documentation fixes",
      "activity_description": "Update marbles02_private tutorial commands for newline-safe base64 environment-variable construction, correct both reported examples, and validate the commands against the documented shell workflow.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "Packaging, CI, documentation, and final cleanup",
      "activity_description": "Add or update module metadata, license and API documentation, CI jobs, dependency checks, release notes, examples, and final cleanup; address review findings and prepare the increment for submission.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 150
  }
}

